"""Debates do cotidiano (terceira leva, novembro de 2026). Mesmo formato de debates.py."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
TEMAS_DB3 = ['Cotidiano']
CO = TEMAS_DB3[0]
VP, RS, AN = 'Vida pessoal e relações', 'Riqueza e sociedade', 'Animais'

DEBATES3 = [
dict(s='duplo-padrao-sexual', n='Duplo padrão sexual: julgar homens e mulheres igual?', t=VP, r='O homem que tem muitos parceiros é “garanhão”; a mulher, recebe outro nome. O duplo padrão é quase universal. Ele tem alguma defesa?',
 v='Em quase todas as culturas, a mesma conduta sexual é aprovada ou tolerada em homens e condenada em mulheres. O duplo padrão aparece em palavras, piadas, leis antigas e nas pesquisas de atitude. A pergunta ética é se existe alguma diferença relevante que o justifique.',
 lados=[('Contra o duplo padrão', ['Imparcialidade: o mesmo ato, julgado de forma diferente só pelo sexo de quem o pratica, é o padrão de todo preconceito. Quem defende a diferença precisa apontar o que muda, além do sexo.', 'As justificativas usuais (risco de gravidez, “natureza”) descrevem fatos que não geram deveres diferentes: a gravidez envolve dois, e a biologia não diz o que é certo.', 'Consequências: o duplo padrão sustenta assédio, controle sobre o corpo das mulheres, violência de “honra” e a culpabilização de vítimas.', 'A mesma conduta não pode ser virtude em um e vício em outro: a ética das virtudes também exige coerência.']),
        ('O que se diz em defesa, e por que não se sustenta', ['“É a natureza”: mesmo que diferenças de comportamento existam em média, descrever não é prescrever; e a variação entre indivíduos é maior do que entre os sexos.', '“Tradição e cultura”: toda discriminação já foi tradição; o argumento vale igualmente contra o fim de qualquer injustiça.', '“Proteger as mulheres”: controle disfarçado de proteção, que a própria pessoa protegida não pediu.'])],
 c=['A crítica ao duplo padrão não diz que toda conduta sexual é boa: diz que o critério tem de ser o mesmo. Pode-se valorizar fidelidade ou moderação, desde que para todos.', 'O duplo padrão também prejudica homens, ao pressionar por desempenho e ao tratar a recusa como fraqueza.', 'A mudança de atitude é real, mas desigual: pesquisas mostram que o padrão persiste mesmo entre quem o rejeita em teoria.'],
 p=('forte', 'Não há defesa filosófica do duplo padrão: nenhuma diferença relevante entre homens e mulheres justifica julgar o mesmo ato de duas formas, e as consequências do padrão são danosas. O que fica em aberto é só o conteúdo do critério único, que cada pessoa pode fixar onde quiser, desde que o aplique a todos.'),
 teorias=[('deontologia-kantiana', 'Kant', 'A máxima “julgo pela conduta” é universalizável; “julgo pelo sexo” não.'), ('utilitarismo-classico', 'Utilitarismo', 'O duplo padrão gera sofrimento (assédio, controle, violência) sem benefício.'), ('etica-das-virtudes', 'Virtudes', 'O que é virtude ou vício não muda com o sexo de quem age.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, sem saber o próprio sexo, ninguém aceitaria a regra dupla.'), ('etica-do-cuidado', 'Cuidado', 'Pergunta quem é ferido pelo padrão; são mulheres, quase sempre.')],
 licoes=['imparcialidade', 'tribalismo-moral', 'igualdade-humana'],
 fx=[('Sexual double standard (Wikipédia)', WE + 'Double_standard#Sexual_double_standards'), ('Feminist Perspectives on Sex and Gender (Stanford Encyclopedia)', SEP + 'feminism-gender/')]),

dict(s='relacionamentos-abertos', n='Relacionamentos abertos e não monogamia', t=VP, r='A monogamia é um padrão moral ou um arranjo entre outros? O que importa: a forma do relacionamento, ou o acordo e a honestidade entre as pessoas?',
 v='Relacionamentos abertos, poliamor e outras formas de não monogamia consensual são acordos em que os parceiros aceitam vínculos afetivos ou sexuais com outras pessoas. A pergunta não é se cada pessoa gostaria disso, e sim se há algo moralmente errado em um arranjo assim entre adultos que o escolhem.',
 lados=[('Não há erro na forma; o que conta é o acordo', ['Autonomia: adultos informados podem definir os termos do próprio relacionamento; o Estado e os outros não têm pretensão sobre isso.', 'O que torna a traição errada é a quebra de um acordo, não o número de parceiros. Onde não há acordo de exclusividade, não há quebra.', 'Honestidade: a não monogamia consensual exige mais conversa explícita do que a monogamia presumida, e pode ser mais honesta, não menos.', 'A monogamia como norma única é recente e cultural; muitas sociedades tiveram outros arranjos.']),
        ('Cautelas e objeções', ['Ciúme, insegurança e assimetria de poder são reais; o “consentimento” de um parceiro pode ser cedência para não perder o outro.', 'Tradições religiosas e parte da ética das virtudes veem a exclusividade como parte do que o amor é, e não como regra externa.', 'Filhos e redes de apoio: arranjos instáveis têm custo para terceiros que não escolheram.', 'A evidência sobre satisfação e duração é mista e vem de amostras pequenas.'])],
 c=['A objeção séria é sobre consentimento genuíno e assimetria, não sobre a forma; ela vale também para relacionamentos monogâmicos com desequilíbrio de poder.', 'Não monogamia consensual é diferente de infidelidade: a primeira é acordo, a segunda é quebra de acordo.', 'A pergunta “o que é melhor para mim?” é diferente de “o que é permitido aos outros?”; o debate ético é sobre a segunda.'],
 p=('parcial', 'A maior parte dos filósofos morais não vê erro intrínseco na não monogamia consensual: o que a ética exige de um relacionamento é consentimento informado, honestidade e cuidado com terceiros, e isso vale para qualquer forma. As cautelas sobre consentimento sob pressão e sobre filhos são sérias, mas valem para todos os arranjos. A preferência pela monogamia é legítima como escolha pessoal, não como norma para os outros.'),
 teorias=[('deontologia-kantiana', 'Kant', 'O que importa é não usar ninguém como meio nem enganar; a forma do acordo é livre.'), ('utilitarismo-classico', 'Utilitarismo', 'Depende do bem-estar dos envolvidos, inclusive terceiros; nenhuma forma vence a priori.'), ('etica-das-virtudes', 'Virtudes', 'Dividida: fidelidade como virtude, ou honestidade e generosidade como as virtudes que importam.'), ('contratualismo-escanloniano', 'Scanlon', 'Que princípios os parceiros não poderiam rejeitar? Os que exigem acordo explícito e saída possível.'), ('etica-do-cuidado', 'Cuidado', 'Atenção às necessidades de cada um, inclusive do mais vulnerável no arranjo.')],
 licoes=['imparcialidade', 'dilemas-do-cotidiano', 'etica-do-cuidado'],
 fx=[('Non-monogamy (Wikipédia)', WE + 'Non-monogamy'), ('Love (Stanford Encyclopedia)', SEP + 'love/')]),

dict(s='infidelidade', n='Traição', t=VP, r='Quase todos condenam, muitos praticam. O que exatamente é errado na infidelidade, e isso muda alguma coisa?',
 v='Traição é quebrar um acordo de exclusividade, em geral escondendo. Pesquisas mostram condenação quase unânime e prática comum. A pergunta ética é localizar o erro: no sexo com outra pessoa, na mentira, na quebra de promessa, ou no dano?',
 lados=[('Por que é errado', ['Quebra de promessa: a exclusividade foi prometida, e promessas criam expectativas sobre as quais o outro organiza a vida.', 'Engano: a traição quase sempre envolve mentiras continuadas, que tratam o parceiro como alguém que não merece decidir com a verdade (Kant).', 'Dano: o parceiro traído sofre, e a confiança quebrada tem custo para a relação, os filhos e a rede em volta.', 'Caráter: a traição exige dissimulação sustentada, que corrói quem a pratica.'])],
 c=['Se o erro está na quebra de acordo e no engano, e não no sexo, então a não monogamia consensual não é traição, e um casamento sem sexo mas com mentiras pode ser mais desleal do que um caso.', 'Circunstâncias atenuam sem absolver: um relacionamento abusivo ou já terminado de fato muda o peso, não a natureza do ato.', 'A reação social à traição muitas vezes recai mais sobre a mulher, pelo duplo padrão.'],
 p=('forte', 'Há consenso de que a traição é errada, e também sobre o porquê: não pelo sexo em si, e sim pela quebra de uma promessa sobre a qual o outro organizou a vida e pelo engano que a sustenta. Isso tem uma consequência: o remédio contra o desejo de outras pessoas não é esconder, e sim renegociar o acordo ou encerrá-lo com honestidade.'),
 teorias=[('deontologia-kantiana', 'Kant', 'Errado pela mentira e pela promessa quebrada, independentemente do dano.'), ('utilitarismo-classico', 'Utilitarismo', 'Errado pelo sofrimento causado e pela confiança destruída; se ninguém jamais soubesse, a conta fica incômoda.'), ('etica-das-virtudes', 'Virtudes', 'Deslealdade e dissimulação são vícios; a pessoa íntegra renegocia ou termina.'), ('deontologia-pluralista', 'Ross', 'Dever de fidelidade, que só cede a deveres mais fortes, e o desejo não é um.'), ('etica-do-cuidado', 'Cuidado', 'O traído é tratado como alguém cujas necessidades não contam.')],
 licoes=['dilemas-do-cotidiano', 'kant-e-o-imperativo-categorico', 'fraqueza-de-vontade'],
 fx=[('Promises (Stanford Encyclopedia)', SEP + 'promises/'), ('Infidelity (Wikipédia)', WE + 'Infidelity')]),

dict(s='pornografia', n='Pornografia', t=VP, r='Consumir e produzir pornografia entre adultos: liberdade de expressão e prazer sem vítima, ou indústria que explora e molda o desejo?',
 v='A pornografia é consumida por boa parte dos adultos e produzida por uma indústria enorme. O debate ético tem três camadas: o consumo é errado em si? A produção explora quem atua? E o conteúdo afeta as atitudes de quem consome, sobretudo sobre mulheres e consentimento?',
 lados=[('A favor da permissão, com regras', ['Entre adultos consentindo, não há vítima; proibir é paternalismo e censura.', 'Produção regulada, com direitos trabalhistas e verificação de consentimento e idade, protege mais do que a proibição, que empurra tudo para a clandestinidade.', 'A evidência sobre efeitos em atitudes e comportamento é mista; estudos de larga escala não encontram ligação consistente com violência.', 'Há pornografia feita por e para mulheres e grupos minoritários; o conteúdo não é uma coisa só.']),
        ('Críticas', ['Feminismo abolicionista (MacKinnon, Dworkin): a pornografia dominante eroticiza a subordinação das mulheres e ensina consentimento como coisa a ser vencida.', 'Produção: condições de trabalho, coerção econômica e abuso são documentados, e a verificação de consentimento nas plataformas é frágil.', 'Consumo compulsivo e exposição precoce: parte dos usuários relata dano a si mesmo, e crianças têm acesso fácil.', 'Virtudes: o que o hábito de consumir pessoas como imagens faz com a capacidade de ver pessoas.'])],
 c=['A indústria e o conteúdo são heterogêneos; o argumento contra o pior não vale contra tudo.', 'Separar o que é erro moral do que é problema de regulação: proteção de menores e de quem atua é consenso; o consumo adulto é o que se discute.', 'A objeção feminista sofisticada não pede proibição, e sim crítica do conteúdo e mudança de condições.'],
 p=('aberto', 'Sobre proteção de menores e condições de produção, há consenso de que a regulação precisa ser muito mais forte do que é. Sobre o consumo adulto em si, o debate é real: a defesa pela autonomia e pela falta de vítima direta é forte, e a crítica feminista sobre o que o conteúdo dominante ensina também é; a evidência empírica não decide. A posição mais comum é permitir, regular com rigor e criticar o conteúdo sem censurá-lo.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo (Mill)', 'Permitir entre adultos; regular pelo dano a terceiros, sobretudo a quem produz.'), ('deontologia-kantiana', 'Kant', 'Cautela: tratar pessoas como objetos de uso, mesmo com consentimento, é o que a fórmula da humanidade questiona.'), ('deontologia-de-direitos', 'Direitos', 'Expressão e autonomia de um lado; direitos de quem atua, do outro.'), ('etica-das-virtudes', 'Virtudes', 'O hábito molda o caráter; a pergunta é que olhar ele forma.'), ('etica-do-cuidado', 'Cuidado', 'Começa pelas condições de quem produz, que são o ponto cego do consumo.')],
 licoes=['fazer-e-deixar-acontecer', 'vieses-morais', 'abertura-moral'],
 fx=[('Pornography and Censorship (Stanford Encyclopedia)', SEP + 'pornography-censorship/'), ('Feminist Perspectives on Objectification (Stanford Encyclopedia)', SEP + 'feminism-objectification/')]),

dict(s='dar-dinheiro-na-rua', n='Dar dinheiro a quem pede na rua', t=CO, r='Ajuda ou alimenta um problema? O gesto mais comum de caridade é também o mais discutido.',
 v='Alguém pede dinheiro no sinal ou na calçada. Dar é um ato de compaixão imediata; muitos dizem que não resolve e pode sustentar dependência ou exploração. O que a ética diz sobre o gesto, e sobre a alternativa?',
 lados=[('A favor de dar', ['Há uma pessoa com necessidade concreta à sua frente; recusar por teoria é o viés de omissão em miniatura.', 'A pessoa sabe melhor do que você o que precisa; dinheiro respeita sua autonomia mais do que comida escolhida por você.', 'Estudos com transferências diretas, inclusive a pessoas em situação de rua, mostram que a maior parte gasta em necessidades, não em drogas.', 'A recusa sistemática endurece quem recusa.']),
        ('A favor de dar de outro jeito', ['O mesmo valor, doado a organizações eficazes, faz muito mais bem: salva vidas em vez de aliviar uma hora.', 'Em alguns casos, dar sustenta exploração (crianças usadas para pedir) ou dependência química; a organização local sabe o que acontece ali.', 'Dar na rua é dar a quem pede, não a quem mais precisa; os mais vulneráveis muitas vezes não estão pedindo.', 'A caridade de impulso substitui a pressão por políticas públicas que resolvam.'])],
 c=['O dilema é falso quando apresentado como “dar na rua ou doar bem”: dá para fazer os dois, e a maioria não faz nenhum.', 'O argumento da eficácia é forte sobre onde colocar a maior parte do que se doa; é fraco como razão para negar um trocado a alguém que está com fome agora.', 'Olhar nos olhos e conversar, com ou sem dinheiro, é parte do que se deve a uma pessoa.'],
 p=('parcial', 'O peso da razão: a maior parte do que você pode doar faz mais bem em organizações avaliadas por resultado. Mas isso não é um argumento contra ajudar quem está na sua frente; os dois gestos não competem, e a evidência contra dar dinheiro diretamente é mais fraca do que a intuição “vai gastar errado” sugere. O que a ética condena é usar o argumento da eficácia como desculpa para não fazer nada.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Priorize o que faz mais bem por real; não deixe de ajudar por isso.'), ('etica-do-cuidado', 'Cuidado', 'Responda à pessoa concreta; a atenção já é parte da ajuda.'), ('etica-das-virtudes', 'Virtudes', 'Generosidade sem cálculo, e também sem ingenuidade.'), ('deontologia-kantiana', 'Kant', 'Dever imperfeito de beneficência: ajudar é devido; a forma é livre.'), ('prioritarismo', 'Prioritarismo', 'Quem está pior tem prioridade, e nem sempre é quem pede.')],
 licoes=['pobreza-e-etica-global', 'fazer-e-deixar-acontecer', 'dilemas-do-cotidiano'],
 fx=[('Famine, Affluence, and Morality (Wikipédia)', WE + 'Famine,_Affluence,_and_Morality'), ('GiveDirectly: evidência sobre transferências', 'https://www.givedirectly.org/research-at-give-directly/')]),

dict(s='pequenas-trapacas', n='Pequenas trapaças: pirataria, sonegação, furar fila', t=CO, r='Baixar um filme, não declarar uma renda, passar na frente. “Todo mundo faz” e “não prejudica ninguém”: duas desculpas, examinadas.',
 v='Pequenas violações de regras são tão comuns que parecem invisíveis: pirataria, sonegar um pouco, colar numa prova, furar a fila, pegar o troco a mais. Cada uma parece inofensiva. A ética pergunta pelo padrão, não pelo caso.',
 lados=[('Por que são erradas, mesmo pequenas', ['Universalização: “posso furar a fila quando tenho pressa” só funciona porque os outros não furam; a regra depende da sua exceção.', 'Carona: quem sonega usa estradas e hospitais pagos pelos outros; quem pirateia usa o que foi criado com o pagamento dos outros.', 'Confiança: cada pequena trapaça gasta um pouco da confiança geral, e sociedades com menos confiança são piores para todos, inclusive para o trapaceiro.', 'Caráter: o hábito de se dar exceções forma a pessoa que se dá exceções grandes.']),
        ('O que se diz em defesa', ['“Não prejudica ninguém”: às vezes é verdade no caso isolado, e falso no agregado; o dano é difuso, não inexistente.', '“Todo mundo faz”: descreve, não justifica; e a prevalência é justamente o problema.', '“A regra é injusta”: quando a regra é mesmo injusta (um preço abusivo, um sistema que exclui), a violação pode ter defesa, mas é outro argumento, e exige honestidade sobre o motivo real.', 'Pirataria de obras sem acesso legal, ou de quem não pode pagar, tem defesa consequencialista: ninguém perde uma venda que não existiria.'])],
 c=['A gravidade varia muito: colar prejudica colegas diretamente; piratear um filme sem alternativa legal quase não prejudica ninguém.', 'Regras injustas existem, e a desobediência pode ser legítima, mas o teste é se você diria o motivo em público.', 'O custo social difuso é real e invisível: é a tragédia dos comuns em escala pequena.'],
 p=('parcial', 'O peso está contra: as duas desculpas (“todo mundo faz”, “não prejudica ninguém”) não resistem à universalização nem à conta agregada, e o hábito molda o caráter. As exceções defensáveis são as que se pode declarar em público: regra injusta, acesso inexistente, necessidade real. “Tive vontade” não é uma delas.'),
 teorias=[('deontologia-kantiana', 'Kant', 'A máxima da exceção pessoal não é universalizável; a trapaça depende de os outros não trapacearem.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'A regra “cumpra as regras justas” produz mais bem do que “trapaceie quando parecer inofensivo”.'), ('consequencialismo-de-ato', 'Consequencialismo de ato', 'Caso a caso, parte das trapaças é inofensiva; o problema é confiar no próprio julgamento interessado.'), ('etica-das-virtudes', 'Virtudes', 'Integridade é o que você faz quando ninguém vê.'), ('contratualismo-escanloniano', 'Scanlon', 'Que regras de convivência ninguém rejeitaria? As que proíbem a carona.')],
 licoes=['kant-e-o-imperativo-categorico', 'dilemas-do-cotidiano', 'fraqueza-de-vontade'],
 fx=[('Free rider problem (Wikipédia)', WE + 'Free-rider_problem'), ('Kant’s Moral Philosophy (Stanford Encyclopedia)', SEP + 'kant-moral/')]),

dict(s='cancelamento', n='Cancelamento e vergonha pública', t=CO, r='Punir publicamente quem disse ou fez algo errado: justiça feita por quem não tinha voz, ou linchamento sem defesa nem proporção?',
 v='“Cancelar” é retirar apoio, expor e pressionar, em massa, alguém por uma conduta ou fala considerada errada. Às vezes derruba poderosos que a lei não alcançava; às vezes destrói a vida de alguém por uma frase antiga. A ética pergunta pelo critério.',
 lados=[('O que o cancelamento acerta', ['Deu voz a vítimas que o sistema ignorava; muitos abusos só vieram à tona por pressão pública.', 'Criticar e deixar de consumir são direitos; ninguém é obrigado a apoiar quem despreza.', 'Normas sociais sempre foram mantidas por aprovação e vergonha; a novidade é a escala, não o mecanismo.']),
        ('O que o cancelamento erra', ['Sem proporção: a mesma pena máxima (perder emprego, reputação, segurança) para um crime e para uma piada ruim de dez anos atrás.', 'Sem defesa nem contexto: a multidão julga em minutos, com um trecho, e não há recurso.', 'Sem fim: não há cumprimento de pena nem perdão; a punição é permanente e se reativa a cada busca.', 'Efeito sobre todos: o medo de errar em público silencia a dúvida e a mudança de ideia, que são o que a ética precisa.', 'Costuma atingir os mais fracos: o poderoso sobrevive; o anônimo não.'])],
 c=['Exigir consequências para condutas graves e comprovadas é diferente de punir uma fala infeliz; o debate mistura as duas.', 'Quem cancela também é responsável pelo que faz, e “eu só compartilhei” é o viés de omissão invertido: o dano é causado por muitos, e por isso ninguém se sente autor.', 'A alternativa não é silêncio, e sim crítica proporcional, com espaço para resposta e para mudança.'],
 p=('parcial', 'O peso está contra o cancelamento como prática: ele falha nos três critérios que toda punição justa exige, proporção, defesa e possibilidade de reparação, e seu efeito sobre o debate público é o oposto do que a ética pede. O que ele acerta, dar consequências a abusos reais que o sistema ignorava, pode ser feito com crítica pública proporcional, que é um direito e um dever.'),
 teorias=[('deontologia-de-direitos', 'Direitos', 'Criticar é direito; punir sem defesa nem proporção viola direitos básicos.'), ('utilitarismo-classico', 'Utilitarismo', 'O custo (vidas destruídas, debate silenciado) supera o benefício na maior parte dos casos.'), ('etica-das-virtudes', 'Virtudes', 'A indignação é virtude quando proporcional; em multidão, vira crueldade.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, sem saber se seria o cancelado, ninguém aceitaria a regra.'), ('etica-do-cuidado', 'Cuidado', 'Pergunta o que a pessoa que errou precisa para mudar; raramente é destruição.')],
 licoes=['como-discutir-etica', 'abertura-moral', 'vieses-morais'],
 fx=[('Online shaming (Wikipédia)', WE + 'Online_shaming'), ('So You’ve Been Publicly Shamed', 'https://www.google.com/search?tbm=bks&q=Jon+Ronson+So+You%27ve+Been+Publicly+Shamed'), ('Legal Punishment (Stanford Encyclopedia)', SEP + 'legal-punishment/')]),

dict(s='deveres-com-os-pais', n='O que devemos aos pais?', t=CO, r='Cuidar dos pais na velhice: dívida, gratidão, amizade ou escolha? E quando eles não cuidaram de nós?',
 v='Quase todas as tradições afirmam deveres dos filhos para com os pais, e a maioria das pessoas sente que os tem. A filosofia pergunta de onde vêm: de uma dívida pelo que os pais fizeram, de gratidão, da relação que existe, ou de um dever geral de ajudar quem precisa? A resposta muda o que se deve, e a quem.',
 lados=[('Há deveres especiais', ['Gratidão: os pais deram vida, cuidado e sacrifício; a gratidão gera deveres, mesmo que não um contrato.', 'Relação: Jane English argumentou que os deveres vêm da amizade em curso, não de dívida; o que se deve é o que amigos devem, na medida da relação.', 'Vulnerabilidade: na velhice, os pais dependem dos filhos como os filhos dependeram deles; a ética do cuidado vê aí o modelo da obrigação.', 'Confucionismo: a piedade filial é a raiz de todas as virtudes.']),
        ('Limites e objeções', ['Ninguém pediu para nascer; o “dever” de retribuir algo não solicitado é frágil (Norman Daniels).', 'Pais abusivos ou ausentes: a dívida, se existe, foi criada pelo cuidado, e sem cuidado não há dívida; a relação de English, nesse caso, não existe.', 'Deveres filiais têm sido usados para explorar sobretudo as filhas, que fazem a maior parte do cuidado.', 'A sociedade também deve aos velhos; transferir tudo para a família é injusto com famílias pobres e pequenas.'])],
 c=['A pergunta “o que devo a eles?” é diferente de “o que quero dar?”; muita gente dá mais do que deve, por amor, e isso não é dever.', 'Cuidar não exige fazer tudo sozinho: garantir cuidado é diferente de ser o cuidador.', 'Quando os pais não cuidaram, o dever residual é o que se deve a qualquer pessoa vulnerável, não mais.'],
 p=('parcial', 'A maioria dos filósofos aceita deveres filiais, mas fundados na relação e na gratidão por cuidado recebido, não em uma dívida pelo nascimento. Isso tem consequências: o dever é proporcional ao cuidado e à relação, não é ilimitado, não recai só sobre um filho (em geral a filha), e não existe para quem foi abandonado ou abusado, além do que se deve a qualquer pessoa.'),
 teorias=[('etica-do-cuidado', 'Cuidado', 'A dependência inverte: quem cuidou precisa de cuidado, e a relação pede resposta.'), ('etica-das-virtudes', 'Virtudes (Confúcio, Aristóteles)', 'Gratidão e piedade filial como virtudes centrais, exercidas com juízo.'), ('deontologia-kantiana', 'Kant', 'Gratidão como dever; mas ninguém deve o que não pode, e abuso cancela a relação.'), ('utilitarismo-classico', 'Utilitarismo', 'Cuidar dos pais produz bem; a forma mais eficaz pode não ser pessoal.'), ('contratualismo-escanloniano', 'Scanlon', 'Que princípio sobre filhos e pais ninguém rejeitaria? Cuidado proporcional ao recebido, com apoio social.')],
 licoes=['etica-do-cuidado', 'aristoteles-e-as-virtudes', 'fazer-e-deixar-acontecer'],
 fx=[('Parenthood and Procreation (Stanford Encyclopedia)', SEP + 'parenthood/'), ('What Do Grown Children Owe Their Parents?', 'https://philpapers.org/rec/ENGWDG')]),

dict(s='amizade-e-desacordo', n='Manter amizade com quem pensa muito diferente', t=CO, r='Amigos que votam no oposto, que comem o que você condena, que acham errado o que você faz. Cortar relações é coerência ou tribalismo?',
 v='Cada vez mais pessoas rompem amizades e laços familiares por desacordo político ou moral. De um lado, a ideia de que conviver com certas opiniões é cumplicidade; de outro, a de que o convívio entre quem discorda é a condição para que alguém mude de ideia.',
 lados=[('A favor de manter a relação', ['Pessoas mudam de ideia por quem respeitam, não por quem as rejeita; cortar a relação remove a única influência que você tinha.', 'Bolhas de concordância produzem certeza sem exame; o amigo que discorda é o teste gratuito das suas crenças.', 'Separar a pessoa da opinião é o que a dignidade exige: ninguém se reduz ao que pensa sobre um tema.', 'A história de quem rompeu laços por ideologia é a história das piores épocas.']),
        ('Quando romper se justifica', ['Há diferença entre discordar sobre impostos e defender que certas pessoas não deveriam existir; algumas posições são ataques a quem você ama, ou a você.', 'A relação exige reciprocidade: se o outro usa a amizade para humilhar ou converter, não há amizade a manter.', 'Convivência não é obrigação ilimitada; cada um pode escolher a quem dedicar o tempo.'])],
 c=['A pergunta útil é se a opinião do outro é um desacordo de valores dentro do tolerável, ou uma negação da dignidade de alguém; a maioria dos rompimentos é pelo primeiro tipo, tratado como se fosse o segundo.', 'Manter a relação não exige silêncio: o amigo que discorda e diz é mais útil do que o que concorda.', 'O custo de romper recai sobre as duas pessoas, e sobre a possibilidade de qualquer uma delas mudar.'],
 p=('parcial', 'O peso está com manter a relação na maior parte dos casos: o desacordo é a condição da revisão de crenças, e o rompimento costuma ser tribalismo vestido de princípio. A exceção legítima é a posição que nega a dignidade de alguém, ou a relação em que o desacordo vira agressão. Mesmo aí, o rompimento é uma perda, não uma vitória.'),
 teorias=[('etica-das-virtudes', 'Virtudes (Aristóteles)', 'A amizade é parte da vida boa, e exige franqueza; romper por desacordo trata o amigo como adversário.'), ('deontologia-kantiana', 'Kant', 'Respeito pela pessoa como agente racional, mesmo quando erra.'), ('utilitarismo-classico', 'Utilitarismo', 'Manter o laço costuma produzir mais bem: influência, bem-estar, menos polarização.'), ('etica-do-cuidado', 'Cuidado', 'A relação é o que importa; o desacordo é um dado dela, não seu fim.'), ('contratualismo-escanloniano', 'Scanlon', 'Que regra de convívio ninguém rejeitaria? A que distingue discordar de agredir.')],
 licoes=['como-discutir-etica', 'tribalismo-moral', 'abertura-moral'],
 fx=[('Friendship (Stanford Encyclopedia)', SEP + 'friendship/'), ('A Mente Moralista', WE + 'The_Righteous_Mind')]),

dict(s='palmada', n='Castigo físico em crianças', t=CO, r='“Uma palmada nunca fez mal a ninguém.” A evidência diz outra coisa, e a ética também.',
 v='Bater em crianças para corrigir foi norma em quase toda cultura, e ainda é comum. Mais de sessenta países o proíbem por lei, inclusive o Brasil desde 2014. A pergunta ética é se há diferença relevante entre bater em um adulto, que é crime, e bater em uma criança, que é “educação”.',
 lados=[('Contra', ['Imparcialidade: a única diferença entre a criança e o adulto é que a criança não pode se defender nem ir embora, o que agrava, e não atenua.', 'Evidência: décadas de estudos associam castigo físico a mais agressividade, pior saúde mental e pior relação com os pais, sem ganho em obediência a longo prazo.', 'Ensina que quem é mais forte pode bater, que é a lição oposta da pretendida.', 'Alternativas funcionam: limites claros, consequências lógicas e consistência educam sem dor.']),
        ('O que se diz em defesa, e por que pesa menos', ['“Fui criado assim e estou bem”: sobrevivência não é prova de benefício; e muita gente não está tão bem.', '“Só em último caso, sem raiva”: a pesquisa mostra que o “último caso” é frequente e raramente sem raiva.', '“É diferente de violência”: a diferença está na intenção do adulto; para a criança, é dor imposta por quem deveria proteger.'])],
 c=['A proibição legal não é para prender pais, e sim para orientar; os países que a adotaram viram o castigo cair sem explosão de processos.', 'Pais que batem não são monstros: repetem o que aprenderam, muitas vezes sob estresse; o remédio é apoio, não culpa.', 'Disciplina firme sem violência é mais difícil e exige recursos que nem todos têm; a política pública importa.'],
 p=('forte', 'Há consenso filosófico e empírico contra o castigo físico: não há diferença relevante que o torne aceitável contra crianças e não contra adultos, e a evidência de dano é consistente, sem evidência de benefício. O que resta de debate é sobre apoio aos pais, não sobre a prática.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Dano demonstrado, sem benefício: contra.'), ('deontologia-kantiana', 'Kant', 'A criança é fim em si; a dor imposta a quem não pode consentir viola isso.'), ('deontologia-de-direitos', 'Direitos', 'O direito à integridade física não depende da idade.'), ('etica-do-cuidado', 'Cuidado', 'Quem cuida não causa dor para obter obediência.'), ('etica-das-virtudes', 'Virtudes', 'Paciência e firmeza educam; a raiva descarregada, não.')],
 licoes=['imparcialidade', 'igualdade-humana', 'etica-do-cuidado'],
 fx=[('Spanking and child outcomes (2016)', 'https://doi.org/10.1037/fam0000191'), ('Lei Menino Bernardo (Wikipédia)', 'https://pt.wikipedia.org/wiki/Lei_Menino_Bernardo'), ('Corporal punishment in the home (Wikipédia)', WE + 'Corporal_punishment_in_the_home')]),

dict(s='animais-de-estimacao', n='Ter animais de estimação', t=AN, r='Amamos cães e gatos, e os criamos para depender de nós. Isso é cuidado, é posse, ou as duas coisas? E o que devemos a eles?',
 v='Centenas de milhões de animais vivem como companhia. A maioria das pessoas vê nisso uma relação de afeto; parte da ética animal pergunta se criar seres para depender de nós, comprá-los e vendê-los, confiná-los e decidir tudo por eles é compatível com levar seus interesses a sério.',
 lados=[('A favor, com deveres', ['Donaldson e Kymlicka: animais domesticados são membros da nossa sociedade; a relação não é o problema, e sim seus termos. Devemos a eles cidadania: cuidado, consideração e voz.', 'Para o animal já existente, uma casa com cuidado é melhor do que o abandono ou o abrigo; adotar é um bem claro.', 'A relação enriquece as duas partes, e a evidência de bem-estar animal em bons lares é forte.']),
        ('Críticas', ['Francione: a domesticação criou seres dependentes para servir a nós; o ideal seria não haver mais, e a compra sustenta a criação.', 'Criação comercial: fábricas de filhotes, raças com doenças selecionadas de propósito (braquicefalia), e descarte quando inconveniente.', 'Confinamento e controle: castração, isolamento por horas, dieta e reprodução decididas por outro; o afeto não anula a assimetria.', 'Animais de estimação carnívoros são alimentados com outros animais, em escala enorme.'])],
 c=['Adotar um animal que já existe e comprar de um criador são atos com consequências opostas, e o debate costuma misturá-los.', 'A crítica à domesticação é sobre o futuro (continuar criando) e não condena quem cuida dos que já estão aqui.', 'O que devemos a um animal de companhia é mais do que o costume supõe: espaço, companhia, saúde, e não ser descartado.'],
 p=('parcial', 'Sobre cuidar de animais que já existem, há consenso de que é bom, e de que os deveres são maiores do que o costume reconhece. Sobre continuar criando e vendendo, o peso está contra a criação comercial, sobretudo a de raças adoecidas, e a favor da adoção. A questão de fundo, se a domesticação deveria continuar, segue aberta entre a visão de membros da comunidade e a abolicionista.'),
 teorias=[('sencientismo', 'Sencientismo', 'Os interesses do animal contam por si; a relação é boa se os serve.'), ('deontologia-de-direitos', 'Direitos (Francione)', 'Contra a propriedade de seres sencientes; a favor de cuidar dos existentes.'), ('contratualismo-estendido', 'Zoopolis', 'Cidadania para domesticados: direitos e representação, não abolição.'), ('etica-do-cuidado', 'Cuidado', 'A relação de dependência é o modelo da obrigação; responder a ela é o dever.'), ('utilitarismo-classico', 'Utilitarismo', 'Bem-estar líquido, incluindo os animais usados como ração.')],
 licoes=['animais-e-a-politica', 'especismo', 'etica-animal-na-pratica'],
 fx=[('Zoopolis: A Political Theory of Animal Rights', 'https://willkymlicka.ca/publications/books/animals'), ('Pet (Wikipédia)', WE + 'Pet'), ('Animal Ethics: animais domesticados', 'https://www.animal-ethics.org/pt/')]),

dict(s='consumo-de-luxo', n='Gastar com luxo é errado?', t=RS, r='Um carro caro, uma viagem, um relógio: o dinheiro que compra prazer para você poderia salvar uma vida para outro. Isso torna o gasto errado?',
 v='O argumento de Singer sobre a criança no lago não para nos bilionários: qualquer gasto supérfluo é dinheiro que poderia ir a quem morre por falta dele. Levado a sério, condena a maior parte do consumo das classes médias do mundo. A pergunta é se o argumento está certo, e o que fazer com ele.',
 lados=[('O gasto supérfluo é difícil de justificar', ['O valor de salvar uma vida supera em muito o de qualquer prazer de consumo; a conta não é próxima.', 'Distância e invisibilidade das vítimas não são razões morais; são vieses.', 'O luxo tem custos além da oportunidade perdida: trabalho explorado, emissões, posicionamento social que empurra os outros a gastar.']),
        ('Por que a condenação total falha', ['Exigência: uma vida sem nenhum prazer próprio não é vivível nem sustentável; a moral que exige isso não será seguida por ninguém.', 'Prerrogativa do agente: temos direito a dar algum peso extra aos próprios projetos (Scheffler); o problema é o tamanho do peso, não sua existência.', 'O consumo sustenta empregos; a pergunta é comparativa, e nem todo gasto é pior do que doar.', 'A culpa difusa paralisa; uma meta concreta de doação faz mais bem do que a ansiedade sobre cada compra.'])],
 c=['A diferença entre o luxo de um bilionário e o de uma família de classe média é de escala, mas o argumento é o mesmo, e isso incomoda.', 'A resposta prática que a maioria dos filósofos dá: uma porcentagem crescente da renda para quem precisa, e liberdade com o resto, sem culpa.', 'O status é o motor de boa parte do luxo, e ele é um jogo de soma zero: ninguém fica melhor quando todos gastam mais.'],
 p=('parcial', 'O argumento de Singer está certo sobre uma coisa: a maior parte do gasto supérfluo não se justifica diante do que o mesmo dinheiro faria. Mas a conclusão de que todo luxo é errado exige demais e não funciona como regra. A posição mais defendida é um compromisso real e crescente de doação, e liberdade de gastar o resto, com atenção ao que o consumo custa a outros e ao planeta.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'O gasto supérfluo perde para a doação em quase toda conta; a exigência é o problema.'), ('deontologia-kantiana', 'Kant', 'Dever imperfeito de beneficência, com latitude; luxo não é crime, indiferença é.'), ('etica-das-virtudes', 'Virtudes', 'Temperança e generosidade: o luxo como vício é o que escraviza; a vida boa inclui prazer com medida.'), ('prioritarismo', 'Prioritarismo', 'O ganho de quem está pior vale muito mais do que o do consumidor.'), ('etica-do-cuidado', 'Cuidado', 'Não exige austeridade, mas atenção a quem o consumo deixa de fora.')],
 licoes=['quanto-a-moral-pode-exigir', 'pobreza-e-etica-global', 'somar-priorizar-ou-garantir'],
 fx=[('Famine, Affluence, and Morality (Wikipédia)', WE + 'Famine,_Affluence,_and_Morality'), ('Demandingness objection (Wikipédia)', WE + 'Demandingness_objection'), ('Giving What We Can', 'https://www.givingwhatwecan.org/')]),
]
assert len({d['s'] for d in DEBATES3}) == len(DEBATES3)
